let state = JSON.parse(localStorage.getItem('kindred-state')||'null') || {stage:'login',tab:'discover',index:0,liked:[],passed:[],chats:sampleChats,selectedChat:'maya',filters:false};
const BACKEND_ENABLED = window.KINDRED_CONFIG?.backend === true;
const apiToken = () => sessionStorage.getItem('kindred-token') || '';
let realtimeSocket = null;
async function apiRequest(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(apiToken())headers.Authorization=`Bearer ${apiToken()}`;const response=await fetch(`/api${path}`,{...options,headers,body:options.body===undefined?undefined:JSON.stringify(options.body)});const data=response.status===204?{}:await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Request failed (${response.status}).`);return data}
function fromApiProfile(p){if(!p)return null;return{id:p.id,name:p.displayName,age:p.age,birthDate:p.birthDate||'',gender:p.gender,looking:Array.isArray(p.interestedIn)?p.interestedIn[0]||'Everyone':p.looking||'Everyone',relation:p.relationshipGoal||p.relation,city:p.city||'',bio:p.bio||'',tags:p.interests||p.tags||[],img:p.photoUrl||p.img||'',interestedIn:p.interestedIn||[],chemistryAnswers:p.chemistryAnswers||{},personalityTwin:p.personalityTwin||''}}
function getAge(birthDate){if(!birthDate)return 0;const d=new Date(`${birthDate}T00:00:00Z`),now=new Date();let age=now.getUTCFullYear()-d.getUTCFullYear();if(now.getUTCMonth()<d.getUTCMonth()||(now.getUTCMonth()===d.getUTCMonth()&&now.getUTCDate()<d.getUTCDate()))age--;return Number.isFinite(age)?age:0}
function latestAdultBirthDate(){const d=new Date();d.setUTCFullYear(d.getUTCFullYear()-18);return d.toISOString().slice(0,10)}
let toastTimer;
function save(){const persisted={...state,profile:state.profile?{...state.profile}:undefined};delete persisted.phone;if(persisted.profile)delete persisted.profile.birthDate;localStorage.setItem('kindred-state',JSON.stringify(persisted))}
function notify(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function brand(){return '<div class="brand"><span class="brand-mark">k</span>kindred</div>'}
function showLogin(){state.stage='login';save();render()}
function render(){if(state.stage==='login'||state.stage==='otp')renderLogin();else if(state.stage==='setup')renderSetup();else renderApp()}
function renderLogin(){app.innerHTML=`<div class="auth-shell"><section class="auth-panel">${brand()}<div class="auth-content"><div class="eyebrow">A little more intentional</div><h1>Good things<br>start with hello.</h1><p class="lead">Meet people who are looking for the same kind of connection you are.</p><label class="field-label" for="phone">Your phone number</label><div class="phone-row"><select aria-label="Country code"><option>🇺🇸 +1</option><option>🇮🇳 +91</option><option>🇬🇧 +44</option><option>🇨🇦 +1</option><option>🇦🇺 +61</option></select><input id="phone" type="tel" autocomplete="tel" placeholder="(555) 000-0000" maxlength="16"></div><label class="field-label" for="password" style="margin-top:16px">Password</label><input id="password" type="password" autocomplete="current-password" minlength="12" maxlength="128" placeholder="At least 12 characters"><p class="tiny-note">Sign in or create an account with your phone number and password. No SMS or Twilio account needed. Your number is not verified and stays private.</p><button id="sign-in" class="primary-btn full">Sign in</button><button id="register" class="secondary-btn full" style="margin-top:10px">Create account</button>${BACKEND_ENABLED?'':'<button class="text-btn" id="demo">Explore the demo instead →</button>'}</div><div class="auth-footer">By continuing, you agree to our Terms and Privacy Policy.</div></section><section class="auth-art"><div class="art-copy"><div class="art-tag">More than a first impression</div><h2>Here for what<br>could be.</h2><p>Meet with intention. Take your time. See where a good conversation goes.</p></div></section></div>`;
 const authenticate=async(mode)=>{const input=document.getElementById('phone'),digits=input.value.replace(/\D/g,''),dial=document.querySelector('.phone-row select').value.match(/\+\d+/)?.[0]||'+1',password=document.getElementById('password').value;if(digits.length<7){notify('Enter a valid phone number to continue.');return}if(password.length<12){notify('Use a password with at least 12 characters.');return}state.phone=`${dial}${digits}`;if(BACKEND_ENABLED){try{const result=await apiRequest('/auth/password',{method:'POST',body:{phone:state.phone,password,mode}});sessionStorage.setItem('kindred-token',result.token);state.profile=fromApiProfile(result.profile);state.stage=state.profile?'app':'setup'}catch(e){notify(e.message);return}}else state.stage=state.profile?'app':'setup';save();render()};
 document.getElementById('sign-in').onclick=()=>authenticate('login');document.getElementById('register').onclick=()=>authenticate('register');document.getElementById('password').onkeydown=e=>{if(e.key==='Enter')authenticate('login')};
 document.getElementById('demo')?.addEventListener('click',()=>{state.stage=state.profile?'app':'setup';save();render()})}
function renderSetup(){const p=state.profile||{};app.innerHTML=`<div class="setup-shell"><section class="setup-card"><div class="setup-top">${brand()}<div class="steps"><span class="active"></span><span class="active"></span></div></div><div class="eyebrow">Your profile, your pace</div><h1>Let’s make it you.</h1><p class="lead">A few details help us introduce you to people looking for the same kind of connection.</p><div class="form-grid"><div class="field"><label for="name">First name</label><input id="name" placeholder="What should we call you?" value="${escapeHtml(p.name||'')}"></div><div class="field"><label for="birth-date">Date of birth (18+)</label><input id="birth-date" type="date" max="${latestAdultBirthDate()}" value="${escapeHtml(p.birthDate||'')}"></div></div><div class="form-grid"><div class="field"><label for="gender">I identify as</label><select id="gender"><option value="">Choose your gender</option>${['Woman','Man','Non-binary','Self-describe','Prefer not to say'].map(x=>`<option ${p.gender===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="looking">I’d like to meet</label><select id="looking"><option value="">Choose who you’d like to meet</option>${['Women','Men','Everyone'].map(x=>`<option ${p.looking===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>What kind of relationship are you looking for?</label><div class="choice-grid">${[['A long-term relationship','Something lasting'],['A serious relationship','Ready to build'],['Life partner','My person'],['Something meaningful','Open to connection'],['Casual dating','See how it feels'],['Still figuring it out','Let it unfold']].map(([a,b])=>`<button class="choice ${p.relation===a?'selected':''}" data-relation="${a}">${a}<small>${b}</small></button>`).join('')}</div></div><div class="setup-actions"><button class="text-btn" id="setup-back">← Back</button><button class="primary-btn" id="finish">Find my people&nbsp; →</button></div><p class="tiny-note">Kindred is for adults 18+. Your gender and relationship preferences help personalize your recommendations.</p></section></div>`;
 document.querySelectorAll('[data-relation]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-relation]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});document.getElementById('setup-back').onclick=()=>{state.stage='login';save();render()};document.getElementById('finish').onclick=async()=>{const name=document.getElementById('name').value.trim(),birthDate=document.getElementById('birth-date').value,age=getAge(birthDate),gender=document.getElementById('gender').value,looking=document.getElementById('looking').value,relation=document.querySelector('[data-relation].selected')?.dataset.relation;if(!name||age<18||age>120||!gender||!looking||!relation){notify('Enter a valid birth date (18+) and complete each profile field.');return}let profile={name,age,birthDate,gender,looking,relation};if(BACKEND_ENABLED){try{const result=await apiRequest('/profile',{method:'PUT',body:{displayName:name,birthDate,gender,interestedIn:[looking],relationshipGoal:relation,city:'',bio:'',interests:[],photoUrl:''}});profile=fromApiProfile(result.profile)}catch(e){notify(e.message);return}}state.profile=profile;state.stage='app';save();render()}}
function buildLocalTwin(a){const pace={'slow-and-steady':'slow-and-steady','balanced':'balanced','spontaneous':'spontaneous'}[a.connectionPace]||'thoughtful';const communication={'thoughtful-texts':'thoughtful texter','voice-notes':'voice-note lover','face-to-face':'in-person communicator'}[a.communication]||'curious communicator';const energy={'cozy-and-quiet':'cozy at heart','a-little-of-both':'socially balanced','always-out':'always up for a plan'}[a.socialEnergy]||'open to connection';return `Your Personality Twin is ${pace}, a ${communication}, and ${energy}. You tend to feel most connected when people respect your pace and make room for honest, comfortable conversation.`}
async function renderChemistry(v){let answers=state.profile?.chemistryAnswers||state.chemistryAnswers||{},twin=state.profile?.personalityTwin||'';if(BACKEND_ENABLED){try{const result=await apiRequest('/chemistry');answers=result.answers||{};twin=result.personalityTwin||''}catch(e){notify(e.message)}}v.innerHTML=`<div class="section-title"><div><div class="eyebrow">Get to know your connection style</div><h1>Digital Chemistry Test.</h1><p>Six quick picks help Kindred understand what comfortable connection means to you.</p></div></div><div class="chemistry-layout"><form class="chemistry-form" id="chemistry-form">${chemistryQuestions.map((q,i)=>`<fieldset class="chem-question"><legend><span>${String(i+1).padStart(2,'0')}</span>${q.title}</legend><div class="chem-options">${q.options.map(([value,label])=>`<label class="chem-option"><input type="radio" name="${q.key}" value="${value}" ${answers[q.key]===value?'checked':''} required><span>${label}</span></label>`).join('')}</div></fieldset>`).join('')}<button class="primary-btn full" type="submit">Save my chemistry</button><p class="tiny-note">Your answers are private. We use them to rank mutual comfort, not to decide who you should date.</p></form><aside class="personality-twin"><div class="twin-orbit">✧</div><div class="eyebrow">Your AI-inspired profile</div><h2>Personality Twin</h2><p id="twin-copy">${escapeHtml(twin||'Finish the test to reveal your connection style.')}</p><div class="twin-note">A reflection of your choices, not a diagnosis or a promise about compatibility.</div><button class="secondary-btn" id="chemistry-discover">See your matches</button></aside></div>`;document.getElementById('chemistry-form').onsubmit=async e=>{e.preventDefault();const formData=new FormData(e.currentTarget),next=Object.fromEntries(chemistryQuestions.map(q=>[q.key,formData.get(q.key)]));try{let result={answers:next,personalityTwin:buildLocalTwin(next)};if(BACKEND_ENABLED)result=await apiRequest('/chemistry',{method:'PUT',body:{answers:next}});state.chemistryAnswers=result.answers;state.profile={...(state.profile||{}),chemistryAnswers:result.answers,personalityTwin:result.personalityTwin};save();document.getElementById('twin-copy').textContent=result.personalityTwin;notify('Your Personality Twin is ready. Mutual comfort scores are updated.')}catch(error){notify(error.message)}};document.getElementById('chemistry-discover').onclick=()=>{state.tab='discover';save();renderApp()}}
function currentPerson(){return people.find(p=>!state.passed.includes(p.id)&&!state.liked.includes(p.id))}
function renderApp(){initializeKindredCallPresence();const nav=[['discover','⌕','Discover',''],['likes','♡',BACKEND_ENABLED?'Matches':'Likes',BACKEND_ENABLED?'':state.liked.length||''],['messages','▤','Messages',BACKEND_ENABLED?'':Object.keys(state.chats).length||''],['profile','◉','My profile',''],['chemistry','✧','Chemistry','']];app.innerHTML=`<div class="app-shell"><aside class="sidebar">${brand()}<div class="nav-label">Your space</div>${nav.map(([id,ico,label,count])=>`<button class="nav-btn ${state.tab===id?'active':''}" data-tab="${id}"><span class="nav-ico">${ico}</span><span>${label}</span>${count?`<span class="nav-count">${count}</span>`:''}</button>`).join('')}<div class="sidebar-bottom"><div class="nav-label">A little reminder</div><div class="surface-card" style="padding:13px;margin:0 3px 15px"><p style="font-size:11px">Good connections take time. Be kind, be curious, be yourself.</p></div><div class="profile-mini"><img class="avatar" src="${image(state.profile?.img||'photo-1534528741775-53994a69daeb',100)}"><div>${escapeHtml(state.profile?.name||'Your profile')}<small>${escapeHtml(state.profile?.relation||'Looking for connection')}</small></div></div></div></aside><section class="main-area"><div class="topbar"><div class="topbar-note">${greeting()}, ${escapeHtml(state.profile?.name||'friend')} <span>✳</span></div><div class="topbar-actions"><button class="icon-btn" id="notif" aria-label="Enable notifications" title="Enable browser notifications">♧<i class="online-dot"></i></button><button class="icon-btn" id="profile-shortcut" aria-label="Profile">☺</button></div></div><div id="view"></div></section><nav class="mobile-nav">${nav.map(([id,ico,label])=>`<button class="${state.tab===id?'active':''}" data-tab="${id}"><b>${ico}</b>${label}</button>`).join('')}</nav></div>`;
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;save();renderApp()});document.getElementById('notif').onclick=()=>requestKindredNotifications();document.getElementById('profile-shortcut').onclick=()=>{state.tab='profile';renderApp()};const v=document.getElementById('view');if(state.tab==='discover')renderDiscover(v);if(state.tab==='likes')renderLikes(v);if(state.tab==='messages')renderMessages(v);if(state.tab==='profile')renderProfile(v);if(state.tab==='chemistry')renderChemistry(v)}
function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<18?'Good afternoon':'Good evening'}
function remoteImage(p,w=700){return image(p.photoUrl||'photo-1524504388940-b1c1722653e1',w)}
async function renderApiDiscover(v){const query=state.query||'';v.innerHTML=`<div class="discover-head"><div><div class="eyebrow">A good place to begin</div><h1>People worth meeting.</h1><p>People ranked by shared chemistry and mutual comfort.</p></div><button class="filter-btn" id="edit-profile">Edit profile</button></div><form class="discover-search" id="api-search"><label for="profile-search">Find your kind of person</label><div class="search-control"><span aria-hidden="true">⌕</span><input id="profile-search" type="search" placeholder="Search names, places, interests…" value="${escapeHtml(query)}"><button type="submit">Search</button></div></form><div id="api-discover-results"><div class="empty-state"><p>Finding your people…</p></div></div>`;document.getElementById('edit-profile').onclick=()=>{state.stage='setup';render()};document.getElementById('api-search').onsubmit=e=>{e.preventDefault();state.query=document.getElementById('profile-search').value.trim();save();renderApiDiscover(v)};try{const result=await apiRequest(`/profiles?search=${encodeURIComponent(query)}`);if(!v.isConnected)return;const profiles=result.profiles||[],container=document.getElementById('api-discover-results');if(query){container.innerHTML=`<section class="search-results"><div class="search-result-head"><div><div class="eyebrow">Your search</div><h2>${profiles.length?`${profiles.length} ${profiles.length===1?'person':'people'} to explore`:'No matches just yet'}</h2></div><button class="text-btn" id="clear-api-search">Clear search</button></div>${profiles.length?`<div class="people-grid">${profiles.map(remoteTile).join('')}</div>`:`<div class="empty-state"><div class="emoji">⌕</div><p>Try another name, neighborhood, or interest.</p></div>`}</section>`;document.getElementById('clear-api-search').onclick=()=>{state.query='';save();renderApiDiscover(v)};container.querySelectorAll('[data-api-match]').forEach(b=>b.onclick=()=>{const p=profiles.find(x=>x.id===b.dataset.apiMatch);if(p)sendApiLike(p,v)});return}const p=profiles[0];if(!p){container.innerHTML=`<div class="empty-state"><div class="emoji">✿</div><h2>No new profiles right now.</h2><p>Try search again later as more people join.</p></div>`;return}container.innerHTML=`<div class="discover-layout"><article class="person-card"><img src="${remoteImage(p,900)}" alt="${escapeHtml(p.displayName)}'s profile"><div class="card-top"><span class="pill">✧ &nbsp; ${p.compatibilityScore===null?'Take Chemistry Test':`${p.compatibilityScore}% mutual comfort`}</span></div><div class="card-copy"><h2>${escapeHtml(p.displayName)}, ${p.age}</h2><p>⌖ &nbsp;${escapeHtml(p.city||'Location not added')} &nbsp; · &nbsp; ${escapeHtml(p.relationshipGoal)}</p><div class="bio">${escapeHtml(p.bio||'Let’s start with a good conversation.')}</div><div class="interest-row">${(p.interests||[]).map(x=>`<span class="interest">${escapeHtml(x)}</span>`).join('')}</div></div><div class="card-actions"><button class="round-action" id="api-pass" aria-label="Pass">×</button><button class="round-action like" id="api-like" aria-label="Match">♡</button><button class="round-action" id="api-wave" aria-label="Send a wave">✧</button></div></article><div class="side-stack"><article class="surface-card intent-box"><h3>Your intention</h3><p>Profiles are filtered to your preferences.</p><span class="intent-chip">${escapeHtml(state.profile?.relation||'')}</span></article><article class="surface-card"><h3>Conversation starter</h3><p>Try asking about one of their interests. Curiosity makes a lovely first hello.</p></article></div></div>`;document.getElementById('api-pass').onclick=async()=>{try{await apiRequest(`/profiles/${p.id}/pass`,{method:'POST'});renderApiDiscover(v)}catch(e){notify(e.message)}};document.getElementById('api-like').onclick=()=>sendApiLike(p,v);document.getElementById('api-wave').onclick=()=>sendApiLike(p,v)}catch(e){if(v.isConnected)document.getElementById('api-discover-results').innerHTML=`<div class="empty-state"><h2>Couldn’t load profiles.</h2><p>${escapeHtml(e.message)}</p></div>`}}
function remoteTile(p){return `<article class="person-tile"><img src="${remoteImage(p,500)}" alt="${escapeHtml(p.displayName)}'s profile"><div class="tile-copy"><strong>${escapeHtml(p.displayName)}, ${p.age}</strong><span class="compatibility-badge">${p.compatibilityScore===null?'Take the Chemistry Test':`✧ ${p.compatibilityScore}% mutual comfort`}</span><p>${escapeHtml(p.city||'Location not added')} · ${escapeHtml(p.relationshipGoal)}</p><p class="search-tags">${(p.interests||[]).slice(0,3).map(escapeHtml).join(' · ')}</p><div class="tile-actions"><button class="tile-like" data-api-match="${p.id}">♡ Match</button></div></div></article>`}
async function sendApiLike(profile,v){try{const result=await apiRequest(`/likes/${profile.id}`,{method:'POST',body:{}});if(result.matched){const matchId=result.match.id;state.selectedChat=matchId;const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="modal"><div class="match-heart">♡</div><div class="eyebrow">It's mutual</div><h2>You and ${escapeHtml(profile.displayName)} matched.</h2><p>Say hello and see where the conversation goes.</p><img src="${remoteImage(profile,200)}" class="avatar" style="width:62px;height:62px" alt=""><div class="modal-actions"><button class="secondary-btn" data-close>Keep exploring</button><button class="primary-btn" data-message>Start chatting</button></div></div>`;document.body.append(modal);modal.querySelector('[data-close]').onclick=()=>{modal.remove();renderApiDiscover(v)};modal.querySelector('[data-message]').onclick=()=>{modal.remove();state.tab='messages';renderApp()}}else{notify('Like sent. If they like you too, you’ll match.');renderApiDiscover(v)}}catch(e){notify(e.message)}}
function renderDiscover(v){if(BACKEND_ENABLED){renderApiDiscover(v);return}const person=currentPerson(),liked=state.liked.length,query=(state.query||'').trim().toLowerCase(),searchResults=query?people.filter(p=>!state.liked.includes(p.id)&&!state.passed.includes(p.id)&&[p.name,p.city,p.relation,p.bio,...p.tags].join(' ').toLowerCase().includes(query)):[];v.innerHTML=`<div class="discover-head"><div><div class="eyebrow">A good place to begin</div><h1>People worth meeting.</h1><p>A few thoughtful introductions, picked for you.</p></div><button class="filter-btn" id="filters-toggle">☷ &nbsp; Preferences</button></div><div class="filters ${state.filters?'show':''}" id="filters"><label>Age range<select id="age-filter"><option>24 – 34</option><option>18 – 28</option><option>28 – 40</option><option>35 – 50</option></select></label><label>Distance<select><option>Within 25 miles</option><option>Within 10 miles</option><option>Anywhere</option></select></label><label>Looking for<select><option>${escapeHtml(state.profile?.relation||'A long-term relationship')}</option><option>Any relationship type</option></select></label></div><div class="discover-layout"><div>${person?`<article class="person-card"><img src="${image(person.img,900)}" alt="${person.name}'s profile"><div class="card-top"><span class="pill">✦ &nbsp; Your kind of connection</span><span class="pill verified">✓ Verified</span></div><div class="card-copy"><h2>${person.name}, ${person.age}</h2><p>⌖ &nbsp;${person.city} &nbsp; · &nbsp; ${person.relation}</p><div class="bio">${person.bio}</div><div class="interest-row">${person.tags.map(x=>`<span class="interest">${x}</span>`).join('')}</div></div><div class="card-actions"><button class="round-action" id="pass" aria-label="Pass">×</button><button class="round-action like" id="like" aria-label="Like">♡</button><button class="round-action" id="say-hi" aria-label="Send a wave">✧</button></div></article>`:`<div class="empty-state"><div class="emoji">✿</div><h2>You’re all caught up.</h2><p>Come back soon for more thoughtful introductions.</p><button class="secondary-btn" id="reset-discover">Start over</button></div>`}</div><div class="side-stack"><article class="surface-card intent-box"><div class="intent-title"><h3>Your intention</h3><button class="edit-link" id="edit-profile">Edit</button></div><p>We’ll prioritize people looking for something similar.</p><span class="intent-chip">${escapeHtml(state.profile?.relation||'A long-term relationship')}</span></article><article class="surface-card"><h3>A small thought</h3><p>Profiles are a first hello, not the whole story. Ask a question that gives someone room to surprise you.</p><div class="activity"><strong>Curiosity counts</strong><span>✳</span></div></article><article class="surface-card"><h3>Your week on Kindred</h3><div class="match-preview"><div class="match-avatars">${people.slice(0,3).map(x=>`<img src="${image(x.img,100)}" alt="">`).join('')}</div><span class="match-caption">${liked} people you’ve liked</span></div><div class="activity"><span>New people for you</span><strong>${Math.max(people.length-state.passed.length-state.liked.length,0)}</strong></div><div class="activity"><span>Looking for</span><strong>${escapeHtml(state.profile?.looking||'Everyone')}</strong></div></article></div></div>`;
 v.querySelector('.discover-head').insertAdjacentHTML('afterend',`<form class="discover-search" id="discover-search"><label for="profile-search">Find your kind of person</label><div class="search-control"><span aria-hidden="true">⌕</span><input id="profile-search" type="search" placeholder="Search names, places, interests…" value="${escapeHtml(state.query||'')}"><button type="submit">Search</button>${query?'<button type="button" class="search-clear" aria-label="Clear search">×</button>':''}</div></form>`);if(query){v.querySelector('.discover-layout').classList.add('searching');v.insertAdjacentHTML('beforeend',`<section class="search-results"><div class="search-result-head"><div><div class="eyebrow">Your search</div><h2>${searchResults.length?`${searchResults.length} ${searchResults.length===1?'person':'people'} to explore`:'No matches just yet'}</h2></div><button class="text-btn" id="clear-search">Clear search</button></div>${searchResults.length?`<div class="people-grid">${searchResults.map(searchTile).join('')}</div>`:`<div class="empty-state"><div class="emoji">⌕</div><p>Try another name, neighborhood, or interest.</p></div>`}</section>`)}
 document.getElementById('discover-search').onsubmit=e=>{e.preventDefault();state.query=document.getElementById('profile-search').value.trim();save();renderDiscover(v)};document.getElementById('profile-search').oninput=e=>{const pos=e.target.selectionStart;state.query=e.target.value;renderDiscover(v);const next=document.getElementById('profile-search');next.focus();next.setSelectionRange(pos,pos)};const clear=()=>{state.query='';save();renderDiscover(v)};document.getElementById('search-clear')?.addEventListener('click',clear);document.getElementById('clear-search')?.addEventListener('click',clear);v.querySelectorAll('[data-search-match]').forEach(b=>b.onclick=()=>{const p=people.find(x=>x.id===b.dataset.searchMatch);if(p)match(p,v)});
 document.getElementById('filters-toggle').onclick=()=>{state.filters=!state.filters;renderDiscover(v)};document.getElementById('edit-profile').onclick=()=>{state.stage='setup';render()};if(person){document.getElementById('pass').onclick=()=>{state.passed.push(person.id);state.index++;save();renderDiscover(v)};document.getElementById('like').onclick=()=>match(person,v);document.getElementById('say-hi').onclick=()=>match(person,v,true)}else document.getElementById('reset-discover').onclick=()=>{state.index=0;state.liked=[];state.passed=[];save();renderDiscover(v)}}
function match(person,v,wave=false){if(!state.liked.includes(person.id))state.liked.push(person.id);state.index++;save();if(!state.chats[person.id])state.chats[person.id]=[{text:wave?'A wave from you 👋':'You liked each other — say hello!',mine:true,time:'Now'}];renderApp();const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.innerHTML=`<div class="modal"><div class="match-heart">♡</div><div class="eyebrow">A lovely beginning</div><h2>You and ${person.name} are a match.</h2><p>You’re both looking for a similar kind of connection. A thoughtful hello can make someone’s day.</p><img src="${image(person.img,200)}" class="avatar" style="width:62px;height:62px" alt="${person.name}"><div class="modal-actions"><button class="secondary-btn" data-close>Keep exploring</button><button class="primary-btn" data-message>Say hello</button></div></div>`;document.body.append(overlay);overlay.querySelector('[data-close]').onclick=()=>overlay.remove();overlay.querySelector('[data-message]').onclick=()=>{overlay.remove();state.tab='messages';state.selectedChat=person.id;renderApp()}}
async function renderApiMatches(v){v.innerHTML=`<div class="section-title"><div><div class="eyebrow">A little mutual interest</div><h1>Your matches.</h1><p>Say hello and see where it goes.</p></div></div><div class="empty-state"><p>Loading matches…</p></div>`;try{const {matches=[]}=await apiRequest('/matches');if(!v.isConnected)return;v.innerHTML=`<div class="section-title"><div><div class="eyebrow">A little mutual interest</div><h1>Your matches.</h1><p>Say hello and see where it goes.</p></div></div>${matches.length?`<div class="people-grid">${matches.map(m=>`<article class="person-tile"><img src="${remoteImage(m,500)}" alt="${escapeHtml(m.displayName)}'s profile"><div class="tile-copy"><strong>${escapeHtml(m.displayName)}, ${m.age}</strong><p>${escapeHtml(m.city||'Location not added')} · ${escapeHtml(m.relationshipGoal)}</p><div class="tile-actions"><button class="tile-like" data-open-match="${m.id}">Message</button><button data-voice-match="${m.id}">☎</button></div></div></article>`).join('')}</div>`:`<div class="empty-state"><div class="emoji">♡</div><h2>Your next connection starts here.</h2><p>Like a profile; when they like you back, you’ll match.</p><button class="primary-btn" id="go-discover">Meet people</button></div>`}`;document.getElementById('go-discover')?.addEventListener('click',()=>{state.tab='discover';renderApp()});v.querySelectorAll('[data-open-match]').forEach(b=>b.onclick=()=>{state.selectedChat=b.dataset.openMatch;state.tab='messages';renderApp()});v.querySelectorAll('[data-voice-match]').forEach(b=>b.onclick=()=>{const m=matches.find(x=>x.id===b.dataset.voiceMatch);openCall(m,'voice')})}catch(e){if(v.isConnected)v.innerHTML=`<div class="empty-state"><h2>Couldn’t load matches.</h2><p>${escapeHtml(e.message)}</p></div>`}}
function renderLikes(v){if(BACKEND_ENABLED){renderApiMatches(v);return}const liked=people.filter(p=>state.liked.includes(p.id));v.innerHTML=`<div class="section-title"><div><div class="eyebrow">A little mutual interest</div><h1>Your likes.</h1><p>People you’ve connected with on the way.</p></div></div>${liked.length?`<div class="people-grid">${liked.map(p=>tile(p,'message')).join('')}</div>`:`<div class="empty-state"><div class="emoji">♡</div><h2>Your next connection starts here.</h2><p>When someone catches your eye, send them a like.</p><button class="primary-btn" id="go-discover">Meet people</button></div>`}`;wireTiles(v);if(document.getElementById('go-discover'))document.getElementById('go-discover').onclick=()=>{state.tab='discover';renderApp()}}
function tile(p,action='like'){return `<article class="person-tile"><img src="${image(p.img,500)}" alt="${p.name}'s profile"><div class="tile-copy"><strong>${p.name}, ${p.age} <span style="color:#54765d">✓</span></strong><p>${p.city} · ${p.relation}</p><div class="tile-actions"><button class="tile-like" data-action="${action}" data-person="${p.id}">${action==='message'?'Message':'♡ Like'}</button><button data-action="call" data-person="${p.id}">☎</button></div></div></article>`}
function searchTile(p){return `<article class="person-tile"><img src="${image(p.img,500)}" alt="${p.name}'s profile"><div class="tile-copy"><strong>${p.name}, ${p.age} <span style="color:#6044d7">✳</span></strong><p>${p.city} · ${p.relation}</p><p class="search-tags">${p.tags.slice(0,3).map(escapeHtml).join(' · ')}</p><div class="tile-actions"><button class="tile-like" data-search-match="${p.id}">♡ Match</button></div></div></article>`}
function wireTiles(v){v.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const p=people.find(x=>x.id===b.dataset.person);if(b.dataset.action==='message'){state.tab='messages';state.selectedChat=p.id;state.chats[p.id]??=[];save();renderApp()}else if(b.dataset.action==='call')openCall(p,'voice');else match(p,v)})}
function apiSocket(){if(!window.io)return null;if(!realtimeSocket){realtimeSocket=window.io({autoConnect:false,auth:{token:apiToken()}});realtimeSocket.connect()}return realtimeSocket}
async function renderApiMessagesLegacy(v){v.innerHTML=`<div class="section-title"><div><div class="eyebrow">Good conversations happen here</div><h1>Messages.</h1><p>Loading conversations…</p></div></div>`;try{const {matches=[]}=await apiRequest('/matches');if(!v.isConnected)return;const selected=matches.find(m=>m.id===state.selectedChat)||matches[0];if(!selected){v.innerHTML=`<div class="section-title"><div><div class="eyebrow">It starts with hello</div><h1>Messages.</h1><p>Your conversations will live here.</p></div></div><div class="empty-state"><div class="emoji">✉</div><h2>No matches yet.</h2><p>When someone likes you back, your conversation will show up here.</p><button class="primary-btn" id="go-discover">Meet people</button></div>`;document.getElementById('go-discover').onclick=()=>{state.tab='discover';renderApp()};return}state.selectedChat=selected.id;const {messages=[]}=await apiRequest(`/matches/${selected.id}/messages`);if(!v.isConnected)return;v.innerHTML=`<div class="section-title"><div><div class="eyebrow">Good conversations happen here</div><h1>Messages.</h1><p>Say something kind. See where it goes.</p></div></div><div class="chat-layout"><aside class="chat-list"><h3>Matches</h3>${matches.map(m=>`<button class="chat-person ${m.id===selected.id?'active':''}" data-chat-id="${m.id}"><img src="${remoteImage(m,120)}" alt=""><div><strong>${escapeHtml(m.displayName)}</strong><small>${escapeHtml(m.lastMessage?.body||'Start a conversation')}</small></div></button>`).join('')}</aside><section class="chat-window"><header class="chat-head"><div class="chat-head-person"><img src="${remoteImage(selected,120)}" alt=""><div><strong>${escapeHtml(selected.displayName)}</strong><small>● &nbsp;Matched on Kindred</small></div></div><div class="call-actions"><button class="icon-btn" id="voice-call" title="Start a voice call">☎</button><button class="icon-btn" id="video-call" title="Start a video call">▣</button></div></header><div class="messages" id="messages">${messages.map(m=>`<div class="message ${m.senderId===state.profile?.id?'mine':''}">${escapeHtml(m.body)}<time>${new Date(m.createdAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')}</div><form class="chat-compose" id="compose"><input id="message-input" placeholder="Write a kind hello…" autocomplete="off" aria-label="Message"><button>Send</button></form></section></div>`;const socket=apiSocket();if(socket){socket.emit('match:join',selected.id);socket.off('message:new');socket.on('message:new',()=>{if(state.tab==='messages'&&state.selectedChat===selected.id)renderApiMessages(v)})}v.querySelectorAll('[data-chat-id]').forEach(b=>b.onclick=()=>{state.selectedChat=b.dataset.chatId;renderApiMessages(v)});document.getElementById('compose').onsubmit=async e=>{e.preventDefault();const input=document.getElementById('message-input'),body=input.value.trim();if(!body)return;try{await apiRequest(`/matches/${selected.id}/messages`,{method:'POST',body:{body}});renderApiMessages(v)}catch(err){notify(err.message)}};document.getElementById('voice-call').onclick=()=>openCall({name:selected.displayName},'voice');document.getElementById('video-call').onclick=()=>openCall({name:selected.displayName},'video')}catch(e){if(v.isConnected)v.innerHTML=`<div class="empty-state"><h2>Couldn’t load messages.</h2><p>${escapeHtml(e.message)}</p></div>`}}
function renderMessages(v){if(BACKEND_ENABLED){renderApiMessages(v);return}const ids=Object.keys(state.chats),selected=people.find(p=>p.id===state.selectedChat)||people.find(p=>p.id===ids[0]);if(!selected){v.innerHTML=`<div class="section-title"><div><div class="eyebrow">It starts with hello</div><h1>Messages.</h1><p>Your conversations will live here.</p></div></div><div class="empty-state"><div class="emoji">✉</div><h2>No conversations yet.</h2><p>Like someone in Discover to open a conversation.</p><button class="primary-btn" id="go-discover">Meet people</button></div>`;document.getElementById('go-discover').onclick=()=>{state.tab='discover';renderApp()};return}state.selectedChat=selected.id;const messages=state.chats[selected.id]||[];v.innerHTML=`<div class="section-title"><div><div class="eyebrow">Good conversations happen here</div><h1>Messages.</h1><p>Say something kind. See where it goes.</p></div></div><div class="chat-layout"><aside class="chat-list"><h3>Conversations</h3>${ids.map(id=>{const p=people.find(x=>x.id===id);if(!p)return'';const last=state.chats[id].at(-1);return `<button class="chat-person ${id===selected.id?'active':''}" data-chat="${id}"><img src="${image(p.img,120)}"><div><strong>${p.name}</strong><small>${escapeHtml(last?.text||'Start a conversation')}</small></div></button>`}).join('')}</aside><section class="chat-window"><header class="chat-head"><div class="chat-head-person"><img src="${image(selected.img,120)}"><div><strong>${selected.name}</strong><small>● &nbsp;Here to connect</small></div></div><div class="call-actions"><button class="icon-btn" id="voice-call" title="Start a voice call">☎</button><button class="icon-btn" id="video-call" title="Start a video call">▣</button></div></header><div class="messages" id="messages">${messages.map(m=>`<div class="message ${m.mine?'mine':''}">${escapeHtml(m.text)}<time>${escapeHtml(m.time||'Now')}</time></div>`).join('')}</div><form class="chat-compose" id="compose"><input id="message-input" placeholder="Write a kind hello…" autocomplete="off" aria-label="Message"><button>Send</button></form></section></div>`;
 v.querySelectorAll('[data-chat]').forEach(b=>b.onclick=()=>{state.selectedChat=b.dataset.chat;renderMessages(v)});document.getElementById('voice-call').onclick=()=>openCall(selected,'voice');document.getElementById('video-call').onclick=()=>openCall(selected,'video');document.getElementById('compose').onsubmit=e=>{e.preventDefault();const input=document.getElementById('message-input'),text=input.value.trim();if(!text)return;state.chats[selected.id]??=[];state.chats[selected.id].push({text,mine:true,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});save();renderMessages(v);const box=document.getElementById('messages');box.scrollTop=box.scrollHeight}}
function openCallPreview(person,type){const video=type==='video',personName=person.displayName||person.name||'your match',modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="modal"><div class="eyebrow">${video?'Video':'Voice'} call</div><h2>${video?'See each other.':'Talk it out.'}</h2><p>Call preview with ${escapeHtml(personName)}.</p><div class="modal-visual">${video?'<span>▣</span>':'<span>☎</span>'}</div><div class="call-timer">DEMO CALL PREVIEW</div><p style="margin-top:10px">The backend can relay WebRTC signaling, but the browser media-call flow still needs to be connected.</p><div class="modal-actions"><button class="primary-btn" data-end style="background:#bd6258">Close preview</button></div></div>`;document.body.append(modal);modal.querySelector('[data-end]').onclick=()=>modal.remove()}
function openCall(person,type){return startKindredCall(person,type,person.matchId||person.id||state.selectedChat)}
async function openSelfieCheck(){const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="modal selfie-modal"><button class="selfie-close" aria-label="Close">×</button><div class="eyebrow">Quick selfie check</div><h2>Real you, real quick.</h2><p>Turn on your camera to preview the selfie step. This demo keeps the image on your device and does not identify or verify you.</p><div class="selfie-view"><video autoplay playsinline muted></video><canvas hidden></canvas><div class="selfie-placeholder"><span>✳</span><small>Center your face in the frame</small></div></div><div class="selfie-status">Your selfie won’t be uploaded or saved in this demo.</div><div class="modal-actions"><button class="secondary-btn" data-camera>Turn on camera</button><button class="primary-btn" data-capture disabled>Capture selfie</button></div></div>`;document.body.append(modal);let stream=null;const close=()=>{stream?.getTracks().forEach(t=>t.stop());modal.remove()};modal.querySelector('.selfie-close').onclick=close;modal.querySelector('[data-camera]').onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera is unavailable in this browser context.');stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});const video=modal.querySelector('video');video.srcObject=stream;await video.play();modal.querySelector('.selfie-placeholder').hidden=true;modal.querySelector('[data-capture]').disabled=false;modal.querySelector('[data-camera]').textContent='Camera is on'}catch(e){modal.querySelector('.selfie-status').textContent=e.name==='NotAllowedError'?'Camera access was declined. You can still close this demo.':'Camera unavailable here. Use localhost or HTTPS to try the preview.'}};modal.querySelector('[data-capture]').onclick=()=>{const video=modal.querySelector('video'),canvas=modal.querySelector('canvas');if(video.videoWidth){canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);modal.querySelector('.selfie-placeholder').hidden=false;modal.querySelector('.selfie-placeholder').innerHTML='<span>✓</span><small>Selfie captured on this device</small>';video.pause();video.hidden=true}modal.querySelector('.selfie-status').textContent='Demo complete — this is not identity verification. A secure provider is needed to verify faces.';modal.querySelector('[data-capture]').textContent='Done';modal.querySelector('[data-capture]').onclick=()=>{state.profile.selfieDemo=true;save();close();renderApp()}}}
function renderProfile(v){const p=state.profile||{};v.innerHTML=`<div class="section-title"><div><div class="eyebrow">A little more about you</div><h1>Your profile.</h1><p>This is how you show up for new connections.</p></div><button class="filter-btn" id="edit-profile">Edit profile</button></div><div class="discover-layout"><article class="person-card" style="height:520px;min-height:420px;max-width:440px"><img src="${image(p.img||'photo-1534528741775-53994a69daeb',900)}" alt="Profile preview"><div class="card-top"><span class="pill verified">✳ Your profile preview</span><button class="pill photo-edit" id="upload-photo" type="button">Change photo</button></div><input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" hidden><div class="card-copy"><h2>${escapeHtml(p.name||'Your name')}${p.age?', '+p.age:''}</h2><p>${escapeHtml(p.gender||'Your gender')} &nbsp; · &nbsp;${escapeHtml(p.relation||'Relationship preference')}</p><div class="bio">A good connection starts with showing up as yourself.</div></div></article><div class="side-stack"><article class="surface-card"><h3>About your preferences</h3><p><strong>Gender:</strong> ${escapeHtml(p.gender||'Not set')}<br><strong>Interested in:</strong> ${escapeHtml(p.looking||'Not set')}<br><strong>Relationship:</strong> ${escapeHtml(p.relation||'Not set')}</p><button class="primary-btn" id="edit-profile-2" style="margin-top:15px;padding:10px 13px;font-size:11px">Edit my details</button></article><article class="surface-card verification-card"><div class="verification-icon">✦</div><div><h3>Selfie check ${p.selfieDemo?'· demo done':''}</h3><p>${p.selfieDemo?'You tried the on-device selfie preview. Your face wasn’t saved.':'A quick camera step can help make profiles feel more real.'}</p><button class="edit-link" id="selfie-check">${p.selfieDemo?'Try the demo again':'Try selfie check'} →</button></div></article><article class="surface-card"><h3>Your privacy</h3><p>Your phone number is private and won’t appear on your profile. The selfie demo keeps your camera image on this device and does not verify identity.</p></article><button class="secondary-btn" id="signout">Sign out</button></div></div>`;document.getElementById('edit-profile').onclick=()=>{state.stage='setup';render()};document.getElementById('edit-profile-2').onclick=()=>{state.stage='setup';render()};document.getElementById('selfie-check').onclick=openSelfieCheck;document.getElementById('signout').onclick=()=>{state.stage='login';state.phone='';sessionStorage.removeItem('kindred-token');if(realtimeSocket){realtimeSocket.disconnect();realtimeSocket=null}save();render()}}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function boot(){if(BACKEND_ENABLED){if(!apiToken()){state.stage='login'}else{try{const {profile}=await apiRequest('/me');state.profile=fromApiProfile(profile);state.stage=state.profile?'app':'setup'}catch{sessionStorage.removeItem('kindred-token');state.stage='login'}}}render()}
boot();

async function renderApiMessages(v){
 v.innerHTML='<div class="empty-state"><p>Loading conversations…</p></div>';
 try{
  const {matches=[]}=await apiRequest('/matches');if(!v.isConnected)return;
  const selected=matches.find(m=>m.id===state.selectedChat)||matches[0];
  if(!selected){v.innerHTML='<div class="empty-state"><div class="emoji">✉</div><h2>No matches yet.</h2><p>When someone likes you back, your conversation will show up here.</p><button class="primary-btn" id="go-discover">Meet people</button></div>';document.getElementById('go-discover').onclick=()=>{state.tab='discover';renderApp()};return}
  state.selectedChat=selected.id;
  const [messageResult,callResult]=await Promise.all([apiRequest(`/matches/${selected.id}/messages`),apiRequest(`/matches/${selected.id}/calls`)]);
  if(!v.isConnected)return;
  const messages=messageResult.messages||[],calls=callResult.calls||[];
  const events=[...messages.map(item=>({...item,eventType:'message',at:item.createdAt})),...calls.map(item=>({...item,eventType:'call',at:item.startedAt}))].sort((a,b)=>new Date(a.at)-new Date(b.at));
  v.innerHTML=`<div class="section-title"><div><div class="eyebrow">Good conversations happen here</div><h1>Messages.</h1><p>Say something kind. See where it goes.</p></div></div><div class="chat-layout"><aside class="chat-list"><h3>Matches</h3>${matches.map(m=>`<button class="chat-person ${m.id===selected.id?'active':''}" data-chat-id="${m.id}"><img src="${remoteImage(m,120)}" alt=""><div><strong>${escapeHtml(m.displayName)}</strong><small>${escapeHtml(m.lastMessage?.body||'Start a conversation')}</small></div></button>`).join('')}</aside><section class="chat-window"><header class="chat-head"><div class="chat-head-person"><img src="${remoteImage(selected,120)}" alt=""><div><strong>${escapeHtml(selected.displayName)}</strong><small id="typing-status">● &nbsp;Matched on Kindred</small></div></div><div class="call-actions"><button class="icon-btn" id="voice-call" aria-label="Start voice call" title="Start a voice call">☎</button><button class="icon-btn" id="video-call" aria-label="Start video call" title="Start a video call">▣</button></div></header><div class="messages" id="messages">${events.map(item=>{const time=new Date(item.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});if(item.eventType==='message')return `<div class="message ${item.senderId===state.profile?.id?'mine':''}">${escapeHtml(item.body)}<time>${time}</time></div>`;const missed=item.status==='missed',outgoing=item.callerId===state.profile?.id,label=missed?'Missed call':item.status==='declined'?'Declined call':item.status==='cancelled'?'Call cancelled':item.status==='completed'?`${item.mediaType==='video'?'Video':'Voice'} call`:outgoing?'Outgoing call':'Incoming call';const duration=item.durationSeconds?` · ${Math.floor(item.durationSeconds/60)}:${String(item.durationSeconds%60).padStart(2,'0')}`:'';return `<div class="call-history ${outgoing?'outgoing':'incoming'} ${missed?'missed':''}"><span class="call-history-icon">${item.mediaType==='video'?'▣':'☎'}</span><span><strong>${label}</strong><small>${item.mediaType==='video'?'Video':'Voice'}${duration}</small></span><time>${time}</time></div>`}).join('')}</div><form class="chat-compose" id="compose"><input id="message-input" placeholder="Write a kind hello…" autocomplete="off" aria-label="Message"><button type="submit">Send</button></form></section></div>`;
  const socket=apiSocket();let typingTimer;
  if(socket){socket.emit('match:join',selected.id);socket.off('typing');socket.off('call:log:update');socket.on('typing',event=>{if(event.matchId!==selected.id||event.userId===state.profile?.id)return;const status=document.getElementById('typing-status');if(status)status.innerHTML=event.typing?'✍ &nbsp;Typing…':'● &nbsp;Matched on Kindred'});socket.on('call:log:update',event=>{if(event.matchId===selected.id&&state.tab==='messages'&&state.selectedChat===selected.id)renderApiMessages(v)})}
  v.querySelectorAll('[data-chat-id]').forEach(button=>button.onclick=()=>{state.selectedChat=button.dataset.chatId;renderApiMessages(v)});
  const input=document.getElementById('message-input');
  input.oninput=()=>{if(!socket)return;socket.emit(input.value.trim()?'typing:start':'typing:stop',{matchId:selected.id});clearTimeout(typingTimer);if(input.value.trim())typingTimer=setTimeout(()=>socket.emit('typing:stop',{matchId:selected.id}),1400)};
  input.onblur=()=>{clearTimeout(typingTimer);socket?.emit('typing:stop',{matchId:selected.id})};
  document.getElementById('compose').onsubmit=async event=>{event.preventDefault();const body=input.value.trim();if(!body)return;clearTimeout(typingTimer);socket?.emit('typing:stop',{matchId:selected.id});try{await apiRequest(`/matches/${selected.id}/messages`,{method:'POST',body:{body}});renderApiMessages(v)}catch(error){notify(error.message)}};
  document.getElementById('voice-call').onclick=()=>openCall({name:selected.displayName,photoUrl:selected.photoUrl},'voice');document.getElementById('video-call').onclick=()=>openCall({name:selected.displayName,photoUrl:selected.photoUrl},'video');
 }catch(error){if(v.isConnected)v.innerHTML=`<div class="empty-state"><h2>Couldn’t load messages.</h2><p>${escapeHtml(error.message)}</p></div>`}
}
